fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 1);
        host::display::state_set(2, 0);
        host::display::state_set(3, 0);
        host::display::state_set(4, 0);
        host::display::state_set(7, 50);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(6) == 0;
    host::display::state_set(6, down);
    let round: i32 = host::display::state_get(1);
    let phase: i32 = host::display::state_get(2);
    let num: i32 = 100 + hash(round * 3) % 900;
    let mut delta: i32 = 1 + hash(round * 5) % 9;
    if hash(round * 11) % 2 == 0 { delta = -delta; }
    let mut decoy: i32 = num + delta;
    if decoy < 100 { decoy = num + 9; }
    let real_top: i32 = hash(round * 7) % 2;
    if phase == 2 {
        host::display::clear(0x181008);
        host::display::draw_string(120, 160, "MEMORY FAULT", 0xff4040, 3);
        host::display::draw_string(100, 220, "THE NUMBER WAS", 0x808080, 2);
        host::display::draw_number(370, 214, num, 0xffffff, 3);
        host::display::draw_string(100, 270, "STREAK", 0x808080, 2);
        host::display::draw_number(240, 264, host::display::state_get(4), 0xffffff, 3);
        host::display::draw_string(100, 304, "BEST", 0x808080, 2);
        host::display::draw_number(240, 298, host::display::state_get(5), 0x00ff88, 3);
        host::display::draw_string(110, 370, "TAP TO TRY AGAIN", 0x808080, 2);
        if tap {
            host::display::state_set(0, 0);
        }
    } else if phase == 0 {
        let timer: i32 = host::display::state_get(3) + 1;
        host::display::state_set(3, timer);
        host::display::clear(0x0c0c14);
        host::display::draw_string(140, 100, "MEMORIZE", 0x808080, 2);
        host::display::draw_number(w / 2 - 54, h / 2 - 24, num, 0xffffff, 8);
        if timer >= host::display::state_get(7) {
            host::display::state_set(2, 1);
            host::display::state_set(3, 0);
        }
    } else {
        let mut top_num: i32 = decoy;
        let mut bot_num: i32 = num;
        if real_top == 1 {
            top_num = num;
            bot_num = decoy;
        }
        if tap {
            let mut picked_top: i32 = 0;
            if host::display::pointer_y() < h / 2 { picked_top = 1; }
            if picked_top == real_top {
                let s: i32 = host::display::state_get(4) + 1;
                host::display::state_set(4, s);
                if s > host::display::state_get(5) {
                    host::display::state_set(5, s);
                }
                let mut lim: i32 = host::display::state_get(7) - 2;
                if lim < 24 { lim = 24; }
                host::display::state_set(7, lim);
                host::display::state_set(1, round + 1);
                host::display::state_set(2, 0);
                host::display::state_set(3, 0);
            } else {
                host::display::state_set(2, 2);
            }
        }
        host::display::clear(0x0c0c14);
        host::display::draw_string(110, 20, "WHICH ONE DID YOU SEE", 0x808080, 2);
        host::display::fill_rect(w / 2 - 90, 70, 180, 120, 0x1c2436);
        host::display::draw_number(w / 2 - 40, 110, top_num, 0xffffff, 5);
        host::display::fill_rect(w / 2 - 90, h - 190, 180, 120, 0x1c2436);
        host::display::draw_number(w / 2 - 40, h - 150, bot_num, 0xffffff, 5);
        host::display::draw_number(8, 8, host::display::state_get(4), 0x00ff88, 2);
    }
    host::display::present();
}
